		`{"op":"query","name":"m","start":0,"end":1,"labels":{"k":"a","k":"b"}}`,   // 重复标签键
		`{"name":"m","start":0,"end":1}`,                                           // 缺 op
		`{"op":"query","start":0,"end":1}`,                                         // 缺 name
		`{"op":"query","name":"m","start":0,"end":1} trailing`,                     // 尾随内容
	}
	for _, line := range bad {
		lerr := mustQueryFail(t, store, line)
		if lerr.Index != 0 {
