	if err := json.Unmarshal([]byte(lines[2]), &line4); err != nil {
		t.Fatal(err)
	}
	if line4["status"] != "ok" || line4["added"].(float64) != 1 {
		t.Fatalf("line 4 = %v", line4)
	}
