		`{"op":"query","name":"cpu","start":1000,"end":2000,"labels":{"host":"a"}}`, // 行 5：avg=(2+4)/2=3
		`{"op":"query","name":"cpu","start":3000,"end":4000}`,                      // 行 6：无点，空数组
		`{"op":"bogus","name":"cpu","start":0,"end":1}`,                            // 行 7：未知 op，失败
